{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 2 * 10^5",
      "description": "The length of the string is between 1 and 200,000."
    },
    {
      "id": "P2",
      "expression": "1 <= m <= 2 * 10^5",
      "description": "The number of operations is between 1 and 200,000."
    },
    {
      "id": "P3",
      "expression": "1 <= l <= r <= n",
      "description": "The range of each operation is within the bounds of the string."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "len(output) == n - sum(len(c for _ in range(l, r + 1) if s[i - 1] == c))",
      "description": "The output string length is the original length minus the number of removed characters."
    },
    {
      "id": "Q2",
      "expression": "all(output[i] == s[i] for i in range(n) if not any(l <= i + 1 <= r and s[i] == c for l, r, c in operations))",
      "description": "The output string contains only characters not removed by any operation."
    },
    {
      "id": "Q3",
      "expression": "all(output[i] != output[j] for i in range(n) for j in range(i + 1, n) if any(l <= i + 1 <= r and s[i] == c for l, r, c in operations) and any(l <= j + 1 <= r and s[j] == c for l, r, c in operations))",
      "description": "The output string has no two characters swapped by the operations."
    }
  ],
  "invariants": []
}
